def tag(prefix,name):
    """Resolve namespace-qualified names without changing unrelated package XML."""
    return '{'+ns[prefix]+'}'+name

def serialize(element):
    """Preserve existing prefixes and required namespace declarations."""
    return E.tostring(element,encoding='UTF-8',xml_declaration=True,standalone=True)

def playback_timing(slide,shape_id):
    """Register a native click-to-play video node, targeted to its actual picture shape."""
    assert slide.find('p:timing',ns) is None
    timing=E.Element(tag('p','timing'))
    tn=E.SubElement(timing,tag('p','tnLst'))
    par=E.SubElement(tn,tag('p','par'))
    common=E.SubElement(par,tag('p','cTn'),id='1',dur='indefinite',restart='never',nodeType='tmRoot')
    children=E.SubElement(common,tag('p','childTnLst'))
    video=E.SubElement(children,tag('p','video'))
    node=E.SubElement(video,tag('p','cMediaNode'),vol='80000',showWhenStopped='1')
    ctn=E.SubElement(node,tag('p','cTn'),id='2',fill='hold',display='0')
    conditions=E.SubElement(ctn,tag('p','stCondLst'))
    E.SubElement(conditions,tag('p','cond'),delay='indefinite')
    target=E.SubElement(node,tag('p','tgtEl'))
    E.SubElement(target,tag('p','spTgt'),spid=shape_id)
    extension=slide.find('p:extLst',ns)
    if extension is None:slide.append(timing)
    else:slide.insert(list(slide).index(extension),timing)

